#include <iostream>
#include <string>
#include <vector>
using namespace std;

template <typename T>
class Pouch {
public:
    void put(T x) { goods.push_back(x); }
    int count() { return goods.size(); }
    T at(int i) { return goods[i]; }
private:
    vector<T> goods;
};

int main() {
    int n = 0;
    cin >> n;

    Pouch<int> nums;
    for (int i = 0; i < n; i++) {
        int x = 0;
        cin >> x;
        nums.put(x);
    }

    Pouch<string> names;
    names.put(string("{nameA}"));
    names.put(string("{nameB}"));

    cout << nums.count() << endl;
    cout << names.count() << endl;
    cout << names.at(0) << endl;
    return 0;
}
